        RangedResult Calc(string name,params string[] mods)=>RangedEngine.Calculate(Build(name,mods));
        RangedBuild WithRiven(string name,int rank,params RangedRivenTrait[] traits)
        {
            var b=Build(name);var w=RangedEngine.Weapons.Single(w=>w.Id==b.WeaponId);
            var roll=new RangedRivenRoll(w.Id,rank,traits,RangedRivens.Table.Version,10,"Madurai");
            roll=roll with{Traits=traits.Select(t=>t with{Value=Math.Round(RangedRivens.Range(roll,t).Minimum/.9,1)}).ToArray()};
